INSERT INTO feature VALUES('stall-detector','workflow','Stalls paged by name and escalated to a decision',NULL,'implemented','ordinary',NULL,'`stall:watch` reads the open pull requests every five minutes for a green root left unqueued, an ejected, piled-up, red, conflicting or base-blocked pull request, one queued on a branch that merges nothing into the trunk, or a merged pull request''s refactoring verdict no issue was filed for, and pages each finding to its lane''s seat and the coordinator at once, by name, the page script resolving the name at page time; a finding standing ten minutes after its page puts a stall comment and `status:stalled` on the pull request and pages the coordinator again every ten minutes until it clears, and a seat with no live block is paged to the coordinator. The coordinator''s page ends with the decisions its finding admits, each with its command, `pr:hold` and its arguments among them. A pull request held on purpose is a draft with its reason (`pr:hold`), which no stall counts and no landing lands. `stall:watch --install` runs the detector as a `systemd --user` unit or a `launchd` agent that starts it again 20 seconds after any exit, and `stall:check` names a detector whose last reading is over two intervals old.',NULL,'.config/stall/cases.json',NULL,NULL);
